/**
 * ATDD RED-PHASE — Story 11-2, AC3 PRIMARY PROOF (structural unreachability).
 * Generated by `/bmad-tea AT 11-2` (Murat) 2026-10-13.
 *
 * This is the LOAD-BEARING R-11-3 discharge (party-mode ruling): the real
 * guarantee is not "guardNotProduction throws" (a tripwire for a path that
 * mints nothing) — it is that the harness session logic is structurally
 * unreachable from the app bundle, so it can NEVER ship in a production build.
 *
 * RED NOW: imports `HARNESS_MODULE_ID` from `./auth-harness`, which does not
 * exist yet → `tsc -b` TS2307 + vitest collection failure. Once the harness
 * exists, this test resolves and asserts the invariant below.
 *
 * ENVIRONMENT NOTE: default jsdom env (see auth-harness.test.ts header) — this
 * file uses `node:fs`/`node:path` only, which resolve under jsdom in vitest.
 *
 * SEAM: no new dependency. A `src/**` import scan (regex over the app source
 * tree) is sufficient and deterministic; dependency-cruiser is NOT installed in
 * this repo, so do not reach for it. If the team later adds depcruise, replace
 * the scan with a rule and keep this test as the assertion.
 */
import { readdirSync, readFileSync, statSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { describe, expect, it } from 'vitest'
import { HARNESS_MODULE_ID } from './auth-harness'

const SRC_ROOT = resolve(__dirname, '../../../src')

function walk(dir: string): string[] {
  const out: string[] = []
  for (const name of readdirSync(dir)) {
    const full = join(dir, name)
    if (statSync(full).isDirectory()) out.push(...walk(full))
    else if (/\.(ts|tsx)$/.test(name)) out.push(full)
  }
  return out
}

describe('11-2 AC3 — harness is structurally unreachable from the app bundle', () => {
  it('no src/** module imports the auth-harness (so it is excluded from the Vite production bundle)', () => {
    const offenders: string[] = []
    const needle = HARNESS_MODULE_ID.split('/').pop() as string // 'auth-harness'
    for (const file of walk(SRC_ROOT)) {
      const text = readFileSync(file, 'utf8')
      // Match any import/require/dynamic-import that references the harness module.
      if (
        new RegExp(
          `(import|from|require\\()\\s*['"\`][^'"\`]*${needle}['"\`]`,
        ).test(text)
      ) {
        offenders.push(file.replace(SRC_ROOT, 'src'))
      }
    }
    expect(
      offenders,
      `auth-harness MUST NOT be imported by app source (R-11-3): ${offenders.join(', ')}`,
    ).toEqual([])
  })
})
